    Binary,
    Bytes,
    GB,
    GiB,
    MB,
    MiB,
}

struct Config {
    format: Format,
    apparent_size: bool,
    count_hard_links: bool,
    stay_on_filesystem: bool,
    ignore_dirs: Vec<PathBuf>,
    threads: usize,
    inputs: Vec<PathBuf>,
    stats: bool,
    no_sort: bool,
    no_total: bool,
    is_interactive: bool,
}

impl Config {
    fn from_args() -> Self {
        let mut args: Vec<String> = env::args().collect();
        let mut config = Config {
            format: Format::Binary,
            apparent_size: false,
            count_hard_links: false,
            stay_on_filesystem: false,
            ignore_dirs: vec!["/proc".into(), "/dev".into(), "/sys".into(), "/run".into()],
            threads: 0,
            inputs: Vec::new(),
            stats: false,
            no_sort: false,
            no_total: false,
            is_interactive: false,
        };

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "interactive" | "i" => {
                    config.is_interactive = true;
                }
                "aggregate" | "a" => {
                    // Just a subcommand, skip
                }
                "-f" | "--format" => {
                    i += 1;
                    if i < args.len() {
                        config.format = match args[i].as_str() {
                            "metric" => Format::Metric,
                            "binary" => Format::Binary,
                            "bytes" => Format::Bytes,
                            "gb" => Format::GB,
                            "gib" => Format::GiB,
                            "mb" => Format::MB,
                            "mib" => Format::MiB,
                            _ => Format::Binary,
                        };
                    }
                }
                "-A" | "--apparent-size" => config.apparent_size = true,
                "-l" | "--count-hard-links" => config.count_hard_links = true,
                "-x" | "--stay-on-filesystem" => config.stay_on_filesystem = true,
                "-i" | "--ignore-dirs" => {
                    i += 1;
                    if i < args.len() {
                        config.ignore_dirs = args[i].split_whitespace().map(PathBuf::from).collect();
                    }
                }
                "-t" | "--threads" => {
                    i += 1;
                    if i < args.len() {
                        config.threads = args[i].parse().unwrap_or(0);
                    }
                }
                "--stats" => config.stats = true,
                "--no-sort" => config.no_sort = true,
                "--no-total" => config.no_total = true,
                "-h" | "--help" => {
                    // Print help and exit (simplified)
                    println!("Help message...");
                    std::process::exit(0);
                }
                arg if arg.starts_with('-') => {
                    // Ignore other flags for now or handle them
                }
                _ => {
                    config.inputs.push(PathBuf::from(&args[i]));
                }
            }
            i += 1;
        }

        if config.inputs.is_empty() {
             // If no inputs, and not interactive, use current directory entries
             if !config.is_interactive {
                 if let Ok(entries) = fs::read_dir(".") {
                     for entry in entries.flatten() {
                         config.inputs.push(entry.path());
                     }
                 }
             } else {
                 config.inputs.push(".".into());
             }
        }

        config
    }
}

fn format_size(bytes: u64, format: Format) -> String {
    match format {
        Format::Bytes => format!("{:10} b", bytes),
        Format::Metric => format_unit(bytes, 1000, &["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]),
        Format::Binary => format_unit(bytes, 1024, &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"]),
        Format::GB => format_fixed(bytes, 1000, 3, "GB"),
        Format::GiB => format_fixed(bytes, 1024, 3, "GiB"),
        Format::MB => format_fixed(bytes, 1000, 2, "MB"),
        Format::MiB => format_fixed(bytes, 1024, 2, "MiB"),
    }
}

fn format_unit(bytes: u64, factor: u64, units: &[&str]) -> String {
    let mut value = bytes as f64;
    let mut unit_idx = 0;
    while value > factor as f64 && unit_idx < units.len() - 1 {
        value /= factor as f64;
        unit_idx += 1;
    }

    let unit = units[unit_idx];
    let num_field_width = if factor == 1024 { 7 } else { 7 }; // Adjusted earlier

    if unit == "B" {
        let unit_padding = if factor == 1024 { "  " } else { " " };
        format!("{:>num_field_width$}  {}{}", bytes, unit, unit_padding, num_field_width=num_field_width)
    } else {
        format!("{:>num_field_width$.2} {}", value, unit, num_field_width=num_field_width)
    }
}

fn format_fixed(bytes: u64, factor: u64, pow: u32, unit: &str) -> String {
    let value = bytes as f64 / (factor.pow(pow) as f64);
    format!("{:>6.2} {}", value, unit)
}

struct Entry {
    name: String,
    size: u64,
    is_dir: bool,
}

impl PartialEq for Entry {
    fn eq(&self, other: &Self) -> bool {
        self.size == other.size
    }
}

impl Eq for Entry {}

impl PartialOrd for Entry {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Entry {
    fn cmp(&self, other: &Self) -> Ordering {
        self.size.cmp(&other.size)
    }
}

fn main() {
    let config = Config::from_args();
    // Implementation continues...
    println!("Dua reimplementation");
}
EOF
