                "-l" | "--count-hard-links" => config.count_hard_links = true,
                "-x" | "--stay-on-filesystem" => config.stay_on_filesystem = true,
                "-i" | "--ignore-dirs" => {
                    i += 1;
                    if i < args.len() {
                        // In reality, this could be multiple arguments or comma separated
                        // For now, let's just take the next argument
                        config.ignore_dirs = args[i].split(',').map(PathBuf::from).collect();
                    }
                }
                "-t" | "--threads" => {
                    i += 1;
                    if i < args.len() {
                        config.threads = args[i].parse().unwrap_or(0);
                    }
