                _ => {
                    config.inputs.push(PathBuf::from(&args[i]));
                }
            }
            i += 1;
        }

        config
    }
}

struct TraversalState {
    seen_inodes: HashSet<(u64, u64)>,
    entries_traversed: u64,
    smallest_file: u64,
    largest_file: u64,
}

fn traverse(path: &Path, config: &Config, state: &mut TraversalState, root_dev: Option<u64>) -> u64 {
    let metadata = match if config.apparent_size { fs::symlink_metadata(path) } else { fs::symlink_metadata(path) } {
        Ok(m) => m,
        Err(_) => return 0,
    };

    let dev = metadata.dev();
    let ino = metadata.ino();

    if config.stay_on_filesystem {
        if let Some(rdev) = root_dev {
            if dev != rdev {
                return 0;
            }
        }
    }

    // Check ignore dirs
    if !config.ignore_dirs.is_empty() {
        if let Ok(abs_path) = path.canonicalize() {
             for ignored in &config.ignore_dirs {
                 if abs_path.starts_with(ignored) {
                     return 0;
                 }
             }
        }
    }

    state.entries_traversed += 1;
    let size = if config.apparent_size { metadata.len() } else { metadata.blocks() * 512 };

    if !metadata.is_dir() {
        if !config.count_hard_links {
            if !state.seen_inodes.insert((dev, ino)) {
                return 0;
            }
        }
        if size < state.smallest_file { state.smallest_file = size; }
        if size > state.largest_file { state.largest_file = size; }
        return size;
    }

    let mut total_size = if config.apparent_size { metadata.len() } else { metadata.blocks() * 512 };
    // Wait, for directories, du usually counts the directory itself + its children.
    // dua seems to do the same.

    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            total_size += traverse(&entry.path(), config, state, Some(dev));
        }
    }

    total_size
}

fn main() {
    let mut config = Config::from_args();

    let mut root_entries = Vec::new();
    let mut state = TraversalState {
        seen_inodes: HashSet::new(),
        entries_traversed: 0,
        smallest_file: u64::MAX,
        largest_file: 0,
    };

    let input_paths = if config.inputs.is_empty() {
        let mut p = Vec::new();
        if let Ok(entries) = fs::read_dir(".") {
            for entry in entries.flatten() {
                p.push(entry.path());
            }
        }
        p
    } else {
        config.inputs.clone()
    };

    // Special case: if exactly one directory is passed, show its children
    if input_paths.len() == 1 && input_paths[0].is_dir() {
        let dir_path = &input_paths[0];
        if let Ok(entries) = fs::read_dir(dir_path) {
            for entry in entries.flatten() {
                let path = entry.path();
                let size = traverse(&path, &config, &mut state, None);
                root_entries.push(Entry {
                    name: path.file_name().unwrap().to_string_lossy().to_string(),
                    size,
                    is_dir: path.is_dir(),
                });
            }
        }
    } else {
        for path in &input_paths {
            let size = traverse(path, &config, &mut state, None);
            root_entries.push(Entry {
                name: path.to_string_lossy().to_string(),
                size,
                is_dir: path.is_dir(),
            });
        }
    }

    if !config.no_sort {
        root_entries.sort_by_key(|e| e.size);
    }

    let mut total = 0;
    for entry in &root_entries {
        let size_str = format_size(entry.size, config.format);
        let name_str = if entry.is_dir {
            format!("\x1b[36m{}\x1b[39m", entry.name)
        } else {
            entry.name.clone()
        };
