        let mut config = Config {
            format: Format::Binary,
            apparent_size: false,
            count_hard_links: false,
            stay_on_filesystem: false,
            ignore_dirs: vec!["/proc".into(), "/dev".into(), "/sys".into(), "/run".into()],
            threads: 0,
            inputs: Vec::new(),
            stats: false,
            no_sort: false,
            no_total: false,
            is_interactive: false,
        };
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "interactive" | "i" => config.is_interactive = true,
                "aggregate" | "a" => {}
                "-f" | "--format" => { i += 1; if i < args.len() {
                    config.format = match args[i].as_str() {
                        "metric" => Format::Metric, "binary" => Format::Binary, "bytes" => Format::Bytes,
                        "gb" => Format::GB, "gib" => Format::GiB, "mb" => Format::MB, "mib" => Format::MiB,
                        _ => Format::Binary,
                    };
                }}
                "-A" | "--apparent-size" => config.apparent_size = true,
                "-l" | "--count-hard-links" => config.count_hard_links = true,
                "-x" | "--stay-on-filesystem" => config.stay_on_filesystem = true,
                "-i" | "--ignore-dirs" => { i += 1; if i < args.len() { config.ignore_dirs = args[i].split(',').map(PathBuf::from).collect(); }}
                "-t" | "--threads" => { i += 1; if i < args.len() { config.threads = args[i].parse().unwrap_or(0); }}
                "--stats" => config.stats = true,
                "--no-sort" => config.no_sort = true,
                "--no-total" => config.no_total = true,
                "-V" | "--version" => { println!("dua 2.32.2"); std::process::exit(0); }
                "-h" | "--help" => { println!("A tool to learn about disk usage, fast!"); std::process::exit(0); }
                arg if arg.starts_with('-') => {}
                _ => config.inputs.push(PathBuf::from(&args[i])),
            }
            i += 1;
        }
        config
    }
}
