    size: u64,
    is_dir: bool,
}

struct SharedState {
    seen_inodes: HashSet<(u64, u64)>,
    entries_traversed: u64,
    smallest_file: u64,
    largest_file: u64,
}

fn format_size(bytes: u64, format: Format) -> String {
    match format {
        Format::Bytes => format!("{:>10} b", bytes),
        Format::Metric => format_unit(bytes, 1000, &["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]),
        Format::Binary => format_unit(bytes, 1024, &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"]),
        Format::GB => format_fixed(bytes, 1000, 3, "GB", 10),
        Format::GiB => format_fixed(bytes, 1024, 3, "GiB", 10),
        Format::MB => format_fixed(bytes, 1000, 2, "MB", 11),
        Format::MiB => format_fixed(bytes, 1024, 2, "MiB", 11),
    }
}

fn format_unit(bytes: u64, factor: u64, units: &[&str]) -> String {
    let mut value = bytes as f64;
    let mut unit_idx = 0;
    while value >= factor as f64 && unit_idx < units.len() - 1 {
        value /= factor as f64;
        unit_idx += 1;
    }
    let unit = units[unit_idx];
    let total_width = if factor == 1024 { 11 } else { 10 };
    if unit == "B" {
        let unit_padding = if factor == 1024 { "   B" } else { "  B" };
        format!("{:>width$}{}", bytes, unit_padding, width = total_width - unit_padding.len())
    } else {
        format!("{:>width$.2} {}", val_str(value), unit, width = total_width - unit.len() - 1)
    }
