fn val_str(v: f64) -> String { format!("{:.2}", v) }

fn format_fixed(bytes: u64, factor: u64, pow: u32, unit: &str, total_width: usize) -> String {
    let value = bytes as f64 / (factor as f64).powi(pow as i32);
    format!("{:>width$.2} {}", value, unit, width = total_width - unit.len() - 1)
