    fn new(initial: Vec<(PathBuf, Option<u64>)>) -> Self {
        WorkQueue { queue: Mutex::new(initial), active_workers: Mutex::new(0), condvar: Condvar::new() }
    }
}

fn parallel_traverse(inputs: Vec<(PathBuf, Option<u64>)>, config: Arc<Config>, shared_state: Arc<Mutex<SharedState>>) -> u64 {
    let num_threads = if config.threads == 0 { 8 } else { config.threads };
    let work_queue = Arc::new(WorkQueue::new(inputs));
    let total_size = Arc::new(Mutex::new(0u64));
    let mut handles = Vec::new();
    for _ in 0..num_threads {
