struct WorkQueue { queue: Mutex<Vec<(PathBuf, Option<u64>)>>, active_workers: Mutex<usize>, condvar: Condvar }
impl WorkQueue { fn new(initial: Vec<(PathBuf, Option<u64>)>) -> Self { WorkQueue { queue: Mutex::new(initial), active_workers: Mutex::new(0), condvar: Condvar::new() } } }

fn parallel_traverse(inputs: Vec<(PathBuf, Option<u64>)>, config: Arc<Config>, shared_state: Arc<Mutex<SharedState>>) -> u64 {
    let num_threads = if config.threads == 0 { 8 } else { config.threads };
    let work_queue = Arc::new(WorkQueue::new(inputs));
    let total_size = Arc::new(Mutex::new(0u64));
    let mut handles = Vec::new();
    for _ in 0..num_threads {
        let work_queue = Arc::clone(&work_queue);
        let config = Arc::clone(&config);
        let shared_state = Arc::clone(&shared_state);
        let total_size = Arc::clone(&total_size);
        handles.push(thread::spawn(move || {
            loop {
                let work = {
                    let mut queue = work_queue.queue.lock().unwrap();
                    while queue.is_empty() {
                        if *work_queue.active_workers.lock().unwrap() == 0 { return; }
                        queue = work_queue.condvar.wait(queue).unwrap();
