    }
    for ignored in &config.ignore_dirs { if path.starts_with(ignored) { return 0; } }
    let is_dir = metadata.is_dir();
    let size = if config.apparent_size { metadata.len() } else { metadata.blocks() * 512 };
    {
        let mut s = state.lock().unwrap();
